static char sx__str327[]="init";
static char sx__str328[]="init - Initialize a new project";
static char sx__str329[]="  spectre init [name]";
static char sx__str330[]="Creates sx.mod, sx.lock, src/main.sx and .gitignore in the current";
static char sx__str331[]="directory. The project name defaults to the current directory name.";
static char sx__str332[]="fmt";
static char sx__str333[]="fmt - Format Spectre source files";
static char sx__str334[]="  spectre fmt [-stdio] <file.sx|directory>...";
static char sx__str335[]="  -stdio      Write formatted output to stdout instead of editing in place";
static char sx__str336[]="  -h, -help   Show this help message";
static char sx__str337[]="Directories are searched recursively for .sx files. Other files are";
static char sx__str338[]="ignored. Without -stdio, files are rewritten in place.";
static char sx__str339[]="Calls, signatures and struct/type literals longer than 100";
static char sx__str340[]="characters are split across multiple lines when they can be split";
static char sx__str341[]="safely.";
static char sx__str342[]="critic";
static char sx__str343[]="critic - Point out antipatterns in Spectre source files";
static char sx__str344[]="  spectre critic [-fix] <file.sx|directory>...";
static char sx__str345[]="  -fix        Apply safe fixes to the checked files";
static char sx__str346[]="Directories are searched recursively for .sx files. The exit code is";
static char sx__str347[]="non-zero when issues remain.";
static char sx__str348[]="build";
static char sx__str349[]="build - Build using a configuration from sx.mod";
static char sx__str350[]="  spectre build [config]";
static char sx__str351[]="The configuration name defaults to \"dev\".";
static char sx__str352[]="sx.mod must contain a spectre_version that matches the installed";
static char sx__str353[]="compiler, or the build is rejected. A build configuration may also";
static char sx__str354[]="define compile-time environment variables with an env { } block.";
static char sx__str355[]="install";
static char sx__str356[]="install - Build and install a Spectre project from a repository";
static char sx__str357[]="  spectre install <git-url> [-config <name>] [-shell <shell>]";
static char sx__str358[]="                [-bin-dir <dir>]";
static char sx__str359[]="  -config <name>  Build configuration to use (default: prod, then";
static char sx__str360[]="                  production, release, default, dev, then the first";
static char sx__str361[]="                  configuration in sx.mod)";
static char sx__str362[]="  -shell <shell>  Shell to configure PATH for (bash, zsh, fish,";
static char sx__str363[]="                  nushell, elvish, powershell, sh, ksh, tcsh, ...)";
