static char sx__str365[]="  -bin-dir <dir>  Override the install directory";
static char sx__str366[]="  -h, -help       Show this help message";
static char sx__str367[]="The repository is cloned to a temporary directory, built with the";
static char sx__str368[]="installed Spectre compiler, and the resulting executable is copied";
static char sx__str369[]="into a Spectre-owned binary directory:";
static char sx__str370[]="  ~/.local/share/spectre/bin";
static char sx__str371[]="That directory is then added to PATH for the selected shell.";
static char sx__str372[]="run";
